pred_sql:
SELECT count(*) 
FROM orders 
WHERE order_status = 'delivered';

SELECT 
    ROUND(
        100.0 * SUM(CASE WHEN review_score IN (1, 2) THEN 1 ELSE 0 END) / COUNT(*), 
        2
    ) AS percentage_low_reviews
FROM order_reviews;

SELECT count(*) 
FROM products 
WHERE product_category_name IS NULL;

SELECT 
    ROUND(
        100.0 * COUNT(CASE WHEN order_status = 'canceled' THEN 1 END) / COUNT(*), 
        2
    ) AS cancellation_rate_percentage
FROM orders;
